-- Fixture Firebird para Splitter
CREATE TABLE logs (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    mensagem VARCHAR(200)
);

SET TERM ^ ;

CREATE OR ALTER PROCEDURE sp_gravar_log (p_msg VARCHAR(200))
AS
BEGIN
    INSERT INTO logs (mensagem) VALUES (:p_msg);
    /* Comentário dentro da proc com ; */
END^

SET TERM ; ^

SELECT * FROM logs;
